// ============================================================
// CLOCK GATE - decides whether this 15-min tick is a posting slot.
// Pure logic. No API calls. Nothing here touches your captions.
// ============================================================
const c = $input.first().json;

const out = { ...c, should_post: false, reason: '', jitter_seconds: 0 };

if (c.paused === true || String(c.paused).toLowerCase() === 'true') {
  out.reason = 'Workflow is paused in Config.';
  return [{ json: out }];
}

const tz = c.timezone || 'Asia/Kolkata';
const now = new Date();

const parts = new Intl.DateTimeFormat('en-GB', {
  timeZone: tz, weekday: 'short', year: 'numeric', month: '2-digit',
  day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false,
}).formatToParts(now).reduce((a, p) => (a[p.type] = p.value, a), {});

const weekday = parts.weekday;                                   // "Mon"
const dateStr = `${parts.year}-${parts.month}-${parts.day}`;     // "2026-09-04"
const hh = parseInt(parts.hour, 10);
const mm = parseInt(parts.minute, 10);
const nowMin = hh * 60 + mm;

out.local_time = `${dateStr} ${parts.hour}:${parts.minute} (${weekday}) ${tz}`;

const activeDays = String(c.active_days || '').split(',').map(s => s.trim()).filter(Boolean);
if (activeDays.length && !activeDays.includes(weekday)) {
  out.reason = `${weekday} is not an active day.`;
  return [{ json: out }];
}

const blackouts = String(c.blackout_dates || '').split(',').map(s => s.trim()).filter(Boolean);
if (blackouts.includes(dateStr)) {
  out.reason = `${dateStr} is a blackout date.`;
  return [{ json: out }];
}

// A slot matches if "now" falls inside the 15-minute bucket that
// contains the configured time. Exactly one tick per slot can match,
// so a post can never fire twice for the same slot.
const slots = String(c.post_times || '').split(',').map(s => s.trim()).filter(Boolean);
let matched = null;
for (const s of slots) {
  const [sh, sm] = s.split(':').map(n => parseInt(n, 10));
  if (Number.isNaN(sh) || Number.isNaN(sm)) continue;
  const slotMin = sh * 60 + sm;
  const bucketStart = Math.floor(slotMin / 15) * 15;
  if (nowMin >= bucketStart && nowMin < bucketStart + 15) { matched = s; break; }
}

if (!matched) {
  out.reason = `No slot at ${parts.hour}:${parts.minute}. Slots: ${slots.join(', ')}`;
  return [{ json: out }];
}

// Optional human-like jitter, hard-capped at 14 min so it can never
// bleed into the next bucket.
const jit = Math.max(0, Math.min(14, Number(c.jitter_minutes) || 0));
out.jitter_seconds = jit > 0 ? Math.floor(Math.random() * jit * 60) : 0;

out.should_post = true;
out.slot = matched;
out.reason = `Slot ${matched} matched.`;
return [{ json: out }];

// ============================================================
// PICK NEXT POST - chooses which row goes out, and how many are left.
// Order: priority DESC, then scheduled_for, then sheet order (FIFO).
// ============================================================
const cfg = $('Config').first().json;
const rows = $input.all().map(i => i.json);

const norm = v => String(v ?? '').trim().toLowerCase();
const nowISO = new Date().toISOString();

const pending = rows.filter(r => {
  const s = norm(r.status);
  if (s !== 'pending' && s !== '') return false;
  if (!String(r.image_url ?? '').trim()) return false;
  const sched = String(r.scheduled_for ?? '').trim();
  if (sched && new Date(sched).toString() !== 'Invalid Date' && new Date(sched).toISOString() > nowISO) return false;
  return true;
});

// Recover rows stuck in "processing" for more than 2 hours
// (e.g. n8n restarted mid-run) so nothing is lost forever.
const stuck = rows.filter(r => {
  if (norm(r.status) !== 'processing') return false;
  const t = new Date(String(r.locked_at ?? ''));
  return t.toString() === 'Invalid Date' || (Date.now() - t.getTime()) > 2 * 60 * 60 * 1000;
});

const pool = pending.length ? pending : stuck;

if (!pool.length) {
  return [{ json: { queue_empty: true, remaining: 0, stuck_recovered: 0 } }];
}

pool.sort((a, b) => {
  const pa = Number(a.priority) || 0, pb = Number(b.priority) || 0;
  if (pa !== pb) return pb - pa;
  const sa = String(a.scheduled_for ?? ''), sb = String(b.scheduled_for ?? '');
  if (sa && sb && sa !== sb) return sa < sb ? -1 : 1;
  if (sa && !sb) return -1;
  if (!sa && sb) return 1;
  return 0;
});

const post = pool[0];

return [{
  json: {
    queue_empty: false,
    remaining: pending.length,
    stuck_recovered: pending.length ? 0 : stuck.length,
    id: String(post.id ?? '').trim(),
    image_url: String(post.image_url ?? '').trim(),
    caption: String(post.caption ?? ''),   // <-- passed through VERBATIM, never rewritten
    attempts: Number(post.attempts) || 0,
    run_id: `${$execution.id}-${Date.now()}`,
  }
}];

// Build the row update that claims this post so a second run
// (or a retry) can never publish the same image twice.
const j = $input.first().json;
return [{ json: {
  id: j.id,
  status: 'processing',
  locked_at: new Date().toISOString(),
  run_id: j.run_id,
  attempts: j.attempts + 1,
} }];

// ============================================================
// IMAGE VALIDATOR - deterministic. No AI. No network. No cost.
// Reads the real bytes and checks Instagram's actual rules.
// ============================================================
const cfg  = $('Config').first().json;
const post = $('Pick Next Post').first().json;

const fail = (msg) => [{ json: { image_ok: false, error: msg, ...post } }];

let buf;
try {
  buf = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch (e) {
  return fail('Could not download image: ' + e.message);
}

const sizeMB = buf.length / (1024 * 1024);
const maxMB = Number(cfg.max_file_mb) || 8;
if (sizeMB > maxMB) return fail(`Image is ${sizeMB.toFixed(2)} MB, limit is ${maxMB} MB.`);
if (buf.length < 1024) return fail('File is too small to be a real image.');

// ---- format + dimensions, parsed straight from the file header ----
let width = 0, height = 0, format = '';

if (buf[0] === 0xFF && buf[1] === 0xD8) {
  format = 'jpeg';
  let i = 2;
  while (i < buf.length - 9) {
    if (buf[i] !== 0xFF) { i++; continue; }
    const marker = buf[i + 1];
    if (marker >= 0xC0 && marker <= 0xCF && ![0xC4, 0xC8, 0xCC].includes(marker)) {
      height = buf.readUInt16BE(i + 5);
      width  = buf.readUInt16BE(i + 7);
      break;
    }
    if (marker === 0xD8 || marker === 0x01 || (marker >= 0xD0 && marker <= 0xD7)) { i += 2; continue; }
    i += 2 + buf.readUInt16BE(i + 2);
  }
} else if (buf.slice(0, 8).toString('hex') === '89504e470d0a1a0a') {
  format = 'png';
  width  = buf.readUInt32BE(16);
  height = buf.readUInt32BE(20);
} else if (buf.slice(0, 4).toString('ascii') === 'RIFF' && buf.slice(8, 12).toString('ascii') === 'WEBP') {
  format = 'webp';
} else if (buf.slice(4, 12).toString('ascii').includes('ftyp')) {
  format = 'heic';
}

// Instagram's image publishing endpoint only accepts JPEG.
if (format !== 'jpeg') {
  return fail(`Instagram only accepts JPEG for image posts. This file is "${format || 'unknown'}". Re-export as .jpg.`);
}
if (!width || !height) return fail('Could not read image dimensions - file may be corrupt.');

const minW = Number(cfg.min_width) || 320;
if (width < minW) return fail(`Width ${width}px is below the ${minW}px minimum.`);

const ratio = width / height;
if (ratio < 0.8 || ratio > 1.91) {
  return fail(`Aspect ratio ${ratio.toFixed(3)} is outside Instagram's 0.8 (4:5) to 1.91 (1.91:1) range. ${width}x${height}.`);
}

// ---- duplicate guard: FNV-1a hash over the bytes ----
let h = 0x811c9dc5;
for (let i = 0; i < buf.length; i += 97) {
  h ^= buf[i];
  h = Math.imul(h, 0x01000193) >>> 0;
}
const image_hash = `${buf.length.toString(16)}-${h.toString(16)}`;

if (cfg.block_duplicates === true || String(cfg.block_duplicates).toLowerCase() === 'true') {
  const already = $('Read Queue').all()
    .map(i => i.json)
    .filter(r => String(r.id).trim() !== String(post.id).trim())
    .filter(r => String(r.status ?? '').trim().toLowerCase() === 'posted')
    .some(r => String(r.image_hash ?? '').trim() === image_hash);
  if (already) return fail('This exact image has already been posted (duplicate hash).');
}

return [{ json: {
  ...post,
  image_ok: true,
  error: '',
  width, height, format,
  ratio: Number(ratio.toFixed(3)),
  size_mb: Number(sizeMB.toFixed(2)),
  image_hash,
  dry_run: cfg.dry_run === true || String(cfg.dry_run).toLowerCase() === 'true',
} }];

