// Container is still processing on Meta's side. Poll again,
// but never more than 10 times (~80s) so this can't spin forever.
if ($runIndex >= 10) {
  throw new Error('Instagram container did not finish after 10 polls. Status: ' + JSON.stringify($input.first().json));
}
return $input.all();

// Only reached when Instagram returned a real media ID.
const v = $('Validate Image').first().json;
const media = $('IG: Publish').first().json;
const link = $input.first().json;

if (!media || !media.id) {
  throw new Error('No media ID returned by Instagram - refusing to mark this row as posted.');
}

return [{ json: {
  id: v.id,
  status: 'posted',
  permalink: link.permalink || '',
  media_id: media.id,
  posted_at: new Date().toISOString(),
  image_hash: v.image_hash,
  error_log: '',
} }];

const cfg = $('Config').first().json;
const rows = $input.all().map(i => i.json);
const remaining = rows.filter(r => {
  const s = String(r.status ?? '').trim().toLowerCase();
  return (s === 'pending' || s === '') && String(r.image_url ?? '').trim();
}).length;

const threshold = Number(cfg.low_queue_alert) || 3;
const posted = $('Build Posted Row').first().json;

return [{ json: {
  remaining,
  threshold,
  low: remaining <= threshold,
  permalink: posted.permalink,
  id: posted.id,
} }];

