// Validation failed. Decide: retry next slot, or give up cleanly.
// Either way the row NEVER gets marked "posted".
const cfg = $('Config').first().json;
const j = $input.first().json;
const maxAttempts = Number(cfg.max_attempts) || 2;
const attempts = Number(j.attempts) || 1;

const giveUp = attempts >= maxAttempts;

return [{ json: {
  id: j.id,
  status: giveUp ? 'failed' : 'pending',   // back in the box for one more try
  locked_at: '',
  run_id: '',
  error_log: `[${new Date().toISOString()}] attempt ${attempts}/${maxAttempts}: ${j.error}`,
  _give_up: giveUp,
  _error: j.error,
  _attempts: attempts,
  _max: maxAttempts,
} }];

