// Something blew up mid-run (Instagram down, token dead, sheet locked).
// Release the row back to "pending" so tomorrow's slot picks it up,
// and tell the human exactly which node died.
const e = $input.first().json;
const wf = e.workflow || {};
const err = e.execution?.error || e.error || {};

let id = '';
try { id = e.execution?.lastNodeExecuted ? '' : ''; } catch (x) {}

return [{ json: {
  node: err.node?.name || e.execution?.lastNodeExecuted || 'unknown node',
  message: (err.message || 'no message').slice(0, 500),
  workflow: wf.name || 'Instagram Autopilot',
  execution_url: e.execution?.url || '',
  when: new Date().toISOString(),
} }];

